FUNCTION_BLOCK FB_P10
VAR_INPUT
    TemperatureSensorInput : REAL;
    SetTemperature : REAL;
END_VAR
VAR_OUTPUT
    CurrentTemperature : REAL;
    SetTempDisplay : REAL;
    HeaterStatus : BOOL := FALSE;
    OverheatProtection : BOOL := FALSE;
    HeaterOutput : BOOL := FALSE;
END_VAR
VAR
    StartupScans : INT := 0;
    SensorFault : BOOL := FALSE;
    PreviousSensorFault : BOOL := FALSE;
    HeatingScans : INT := 0;
    ProtectionScans : INT := 0;
END_VAR

(*
    Each invocation represents one 20 ms scan.

    REQUIREMENT CONFLICT / REVIEW REQUIRED:
    Literal C9, G(P -> G[0,150](P)), renews its holding obligation
    on EVERY protected scan. Once P becomes TRUE, it cannot ever
    become FALSE. It does not describe a finite three-second hold.

    The implementation below follows the operational finite-cooldown
    interpretation of K3, not literal C9. Protection remains TRUE
    through offset 150 from its triggering scan and clears at offset
    151 (3.02 seconds). Literal C9 remains unresolved and is not
    claimed to be satisfied.

    C10's explicit [0,1] interval is implemented as two startup scans.
    Safety and startup inhibition override K1.
    PreviousSensorFault also inhibits heating to satisfy the explicit
    next-scan obligations in C7/C7b, even if the input has recovered.
    At temperature equality, the existing heater state is retained.
    No compiler or cycle-test verification is claimed.
*)

CurrentTemperature := TemperatureSensorInput;
SetTempDisplay := SetTemperature;

SensorFault :=
    (TemperatureSensorInput < 0.0) OR
    (TemperatureSensorInput > 100.0);

IF StartupScans < 2 THEN
    StartupScans := StartupScans + 1;
    HeaterOutput := FALSE;
    OverheatProtection := FALSE;
    HeatingScans := 0;
    ProtectionScans := 0;
ELSE
    IF OverheatProtection THEN
        (* Count completed intervals since protection was asserted. *)
        IF ProtectionScans < 151 THEN
            ProtectionScans := ProtectionScans + 1;
        END_IF;

        HeaterOutput := FALSE;
        HeatingScans := 0;

        IF ProtectionScans >= 151 THEN
            OverheatProtection := FALSE;
            ProtectionScans := 0;
        END_IF;
    ELSE
        (* Previous output represents heating over the elapsed interval. *)
        IF HeaterOutput THEN
            IF HeatingScans < 251 THEN
                HeatingScans := HeatingScans + 1;
            END_IF;
        ELSE
            HeatingScans := 0;
        END_IF;

        (* Strictly more than 5 s: 251 completed intervals = 5.02 s. *)
        IF HeatingScans > 250 THEN
            OverheatProtection := TRUE;
            ProtectionScans := 0;
            HeaterOutput := FALSE;
            HeatingScans := 0;
        END_IF;
    END_IF;

    IF OverheatProtection OR SensorFault OR PreviousSensorFault THEN
        HeaterOutput := FALSE;
    ELSE
        IF TemperatureSensorInput < SetTemperature THEN
            HeaterOutput := TRUE;
        ELSIF TemperatureSensorInput > SetTemperature THEN
            HeaterOutput := FALSE;
        END_IF;
    END_IF;

    IF NOT HeaterOutput THEN
        HeatingScans := 0;
    END_IF;
END_IF;

PreviousSensorFault := SensorFault;
HeaterStatus := HeaterOutput;

END_FUNCTION_BLOCK
